#!/usr/bin/env node
/**
 * ULS Passthrough File Copier
 * 
 * Copies the passthrough.js file to the user's project src folder.
 * Reads the target path from uls.config.cjs file.
 * 
 * Usage:
 *   npm run uls-passthrough
 */

const fs = require('fs');
const path = require('path');
const { pathToFileURL } = require('url');

const CONFIG_FILE_NAMES = [
  'uls.config.cjs',
  'uls.config.js',
];

// Get the source passthrough file path
function getPassthroughSourcePath() {
  // Primary location: runtime/passthrough.js (organized structure)
  const localScriptPath = path.resolve(__dirname, '..', 'runtime', 'passthrough.js');
  if (fs.existsSync(localScriptPath)) {
    return localScriptPath;
  }
  
  // Fallback: old location (for backward compatibility)
  const oldLocalPath = path.resolve(__dirname, 'passthrough.js');
  if (fs.existsSync(oldLocalPath)) {
    return oldLocalPath;
  }

  // Fallbacks for older structures or different install resolutions
  const possiblePaths = [
    // When running inside node_modules/uls-v2/src/scripts/create-passthrough.js
    path.resolve(process.cwd(), 'node_modules/uls-v2/src/scripts/runtime/passthrough.js'),
    // Legacy monorepo structure
    path.resolve(__dirname, '../js/uls-primereact/passthrough.js'),
    path.resolve(process.cwd(), 'node_modules/uls-v2/js/uls-primereact/passthrough.js'),
  ];

  for (const possiblePath of possiblePaths) {
    if (fs.existsSync(possiblePath)) {
      return possiblePath;
    }
  }

  throw new Error('Could not find passthrough.js file. Make sure you are running from the ULS repository or have uls-v2 installed.');
}

// Load config file
async function loadConfig() {
  const cwd = process.cwd();

  for (const filename of CONFIG_FILE_NAMES) {
    const filePath = path.join(cwd, filename);
    if (!fs.existsSync(filePath)) {
      continue;
    }

    try {
      const config = await importConfigFile(filePath);
      if (config && typeof config === 'object') {
        return config;
      }
    } catch (err) {
      console.warn(`\n⚠️  Warning: Error loading config file ${filename}: ${err.message}`);
    }
  }

  return null;
}

async function importConfigFile(filePath) {
  try {
    delete require.cache[require.resolve(filePath)];
    return require(filePath);
  } catch (err) {
    if (err.code === 'ERR_REQUIRE_ESM') {
      const module = await import(pathToFileURL(filePath));
      return module.default || module;
    }
    throw err;
  }
}

// Main execution
(async function() {
  try {
    // Load config
    const config = await loadConfig();
    
    if (!config) {
      console.error('\n❌ Error: Could not find uls.config.cjs file.');
      console.error('   Please create uls.config.cjs in your project root with the following structure:');
      console.error('   module.exports = {');
      console.error('     srcPath: "src",  // Path to your project src folder');
      console.error('   };');
      console.error('\n   Or run: npx uls-override --init-config\n');
      process.exit(1);
    }
    
    // Get src path from config
    const srcPath = config.srcPath || config.src || 'src';
    const stylesPath = config.stylesPath || path.join(srcPath, 'styles', 'uls');
    const passthroughTarget =
      config.passthroughPath ||
      (config.stylesPath ? path.join(config.stylesPath, 'passthrough.js') : null) ||
      path.join(srcPath, 'passthrough.js');
    
    // Get source and destination paths
    const sourcePath = getPassthroughSourcePath();
    const projectRoot = process.cwd();
    const destPath = path.isAbsolute(passthroughTarget)
      ? passthroughTarget
      : path.resolve(projectRoot, passthroughTarget);
    const destDir = path.dirname(destPath);
    
    // Ensure destination directory exists
    if (!fs.existsSync(destDir)) {
      console.log(`\n📁 Creating directory: ${path.relative(projectRoot, destDir)}`);
      fs.mkdirSync(destDir, { recursive: true });
    }
    
    // Check if file already exists
    if (fs.existsSync(destPath)) {
      console.log(`\n⚠️  Warning: ${path.relative(projectRoot, destPath)} already exists`);
      console.log('   The file will be overwritten.\n');
    }
    
    // Copy the file
    fs.copyFileSync(sourcePath, destPath);
    
    console.log(`\n✅ Successfully copied passthrough.js`);
    console.log(`   From: ${path.relative(projectRoot, sourcePath)}`);
    console.log(`   To:   ${path.relative(projectRoot, destPath)}`);
    console.log(`\n📝 Next steps:`);
    console.log(`   1. Import passthrough.js in your project:`);
    console.log(`      import passthrough from './passthrough';`);
    console.log(`   2. Use it with PrimeReact components:`);
    console.log(`      <Button pt={passthrough.button} />`);
    console.log(`      <InputText pt={passthrough.inputtext} />`);
    console.log('');
    
  } catch (error) {
    console.error('\n❌ Error:', error.message);
    if (error.stack) {
      console.error('\nStack trace:', error.stack);
    }
    process.exit(1);
  }
})();

